function requestKey(){if(globalThis.crypto.randomUUID)return globalThis.crypto.randomUUID();const b=new Uint8Array(16);globalThis.crypto.getRandomValues(b);return Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');}
'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const h = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=2)=>v==null?'\u2014':Number(v).toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d});
const money=(v,d=0)=>v==null?'\u2014':'\u20b9'+num(v,d);
const pct=(v,d=1)=>v==null?'\u2014':num(v*100,d)+'%';
const day=t=>t?String(t).slice(0,10):'\u2014';
const pill=(text,color='gray')=>`<span class="pill ${color}">${h(text)}</span>`;
const passIcon=x=>`<span class="${x?'check':'cross no'}">${x?'\u2713':'\u00d7'}</span>`;
const state={page:'terminal',mode:'Swing',strategy:'trend_pullback',dataset:null,boot:null,rows:[],analysis:null,result:null,zoom:120,job:null};
let toastTimer;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast'+(error?' error':'');el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',8000);}
async function api(path,body){const response=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Desk-Token':state.boot?.token||''},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw Error('The local service returned an invalid response. Check its terminal.');}if(!response.ok){let msg=data.error||data.detail||'Request failed';if(Array.isArray(msg))msg=msg.map(x=>`${x.loc?.slice(-1)[0]||'Input'}: ${x.msg}`).join('; ');throw Error(msg);}return data;}
const titles={recommendations:'Trade Tips',market:'Find a Stock',desk:'Watchlist',studio:'Stock Chart',terminal:'Research terminal',strategies:'Strategy library',lab:'AI strategy lab',paper:'Paper portfolio',options:'F&O payoff lab',data:'Data & connections',risk:'Risk & audit'};
function heading(title,sub,actions='',eyebrow='INDIAN MARKET RESEARCH'){return `<div class="page-heading"><div><div class="eyebrow">${h(eyebrow)}</div><h1>${h(title)}</h1><p>${h(sub)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stat(label,value,note,cls=''){return `<div class="stat"><div class="stat-label">${h(label)}<span class="symbol">\u25c7</span></div><div class="stat-value ${cls}">${value}</div><div class="stat-note">${note}</div><div class="stat-bar"></div></div>`;}
function demoBanner(synthetic=true){return `<div class="banner"><span class="banner-icon">\u25c8</span><p>${synthetic?'<strong>Synthetic demo workspace.</strong> SIM-* symbols and prices are fictional. Use them to explore the software, not to choose trades.':'<strong>Historical research only.</strong> Imported prices are not live quotes. Data accuracy, corporate actions and trading permissions need independent verification.'}</p></div>`;}
function loading(message='Loading research data'){return `<div class="loading"><span class="spinner"></span><h2>${h(message)}</h2></div>`;}
function empty(title,text){return `<div class="empty-state"><div class="empty-icon">\u25c7</div><h3>${h(title)}</h3><p>${h(text)}</p></div>`;}
function options(list,selected,key='id',label='name'){return list.map(x=>`<option value="${h(x[key])}" ${x[key]===selected?'selected':''}>${h(x[label])}</option>`).join('');}
function strategySpec(){return state.boot.strategies.find(s=>s.id===state.strategy);}
function compatible(){return state.boot.datasets.filter(d=>d.timeframe===strategySpec().timeframe);}
function datasetOptions(selected=state.dataset){return compatible().map(d=>`<option value="${h(d.id)}" ${d.id===selected?'selected':''}>${h(d.symbol)} \u00b7 ${d.timeframe}${d.synthetic?' \u00b7 DEMO':''}</option>`).join('');}
function setDefaultsForMode(mode){state.mode=mode;state.strategy=({Swing:'trend_pullback',Intraday:'opening_range',Delivery:'position_trend'})[mode];const ds=compatible();if(!ds.some(d=>d.id===state.dataset))state.dataset=ds[0]?.id;state.result=null;}
function updateChrome(){for(const b of $$('#navigation [data-page]'))b.classList.toggle('active',b.dataset.page===state.page);$('#breadcrumb').textContent=titles[state.page]||titles.terminal;const kill=state.boot.account.settings.kill_switch;$('#kill-top').classList.toggle('enabled',kill);$('#kill-top').textContent=kill?'\u25c9 Paper entries blocked':'\u25c9 Paper kill switch';}
async function navigate(page){if(!titles[page])page='recommendations';state.page=page;history.replaceState(null,'','#'+page);updateChrome();$('#content').innerHTML=loading();$('#kill-top').hidden=!['paper','risk'].includes(page);try{if(page!=='desk')stopDeskTimer();if(page==='recommendations')await renderRecommendations();else if(page==='market')await renderMarket();else if(page==='desk')await renderDaily();else if(page==='studio')await renderStudio();else if(page==='terminal')await loadTerminal();else if(page==='strategies')renderStrategies();else if(page==='lab')renderLab();else if(page==='paper'){state.boot.account=await api('/account');renderPaper();}else if(page==='data')renderData();else if(page==='risk'){state.boot.account=await api('/account');renderRisk(await api('/audit'));}else if(page==='options')renderOptions();}catch(err){$('#content').innerHTML=heading('Workspace needs attention','Check the message below and try again.')+empty('Could not load this page',err.message);toast(err.message,true);}}
function spark(values,positive){if(!values.length)return '';const lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1;const points=values.map((v,i)=>`${i/(values.length-1)*78},${24-(v-lo)/span*21}`).join(' ');return `<svg class="spark" viewBox="0 0 80 28" aria-label="Recent historical prices"><polyline fill="none" stroke="${positive?'#60cba9':'#dd8595'}" stroke-width="1.4" points="${points}"/></svg>`;}
async function loadTerminal(){state.rows=await api('/scanner?strategy='+state.strategy);if(!state.rows.some(d=>d.id===state.dataset))state.dataset=state.rows[0]?.id;if(!state.dataset){$('#content').innerHTML=heading('Research terminal','Import a compatible dataset to get started.',`<button class="button primary" data-page="data">Import history</button>`)+empty('No compatible history','Daily bars are used for swing and delivery. Intraday strategies use regular-session 15-minute bars.');return;}state.analysis=await api('/analysis/'+state.dataset+'?strategy='+state.strategy);renderTerminal();}
function researchEstimate(){const match=state.boot.experiments.find(e=>e.dataset_id===state.dataset&&e.strategy_name===strategySpec().name);return match||null;}
function planFromAnalysis(){const r=state.analysis.last,s=state.boot.account.settings,capital=s.capital;const entry=r.c,stop=entry-r.atr*1.5,target=entry+r.atr*3;const cost=(entry+stop)*s.cost_bps/20000;const q=stop>0?Math.max(0,Math.floor(Math.min(capital*s.risk_pct/100/(entry-stop+cost),Math.min(capital*s.exposure_pct/100,state.boot.account.cash)/(entry*(1+s.cost_bps/20000))))):0;return {entry,stop,target,q,risk:q*(entry-stop+cost)};}
function scannerRows(){return state.rows.map(d=>`<tr data-symbol="${d.id}" class="${d.id===state.dataset?'selected-row':''}"><td><strong>${h(d.symbol)}</strong><small>${d.synthetic?'Synthetic series':'Imported history'} \u00b7 ${d.timeframe}</small></td><td class="mono">${money(d.close,2)}</td><td class="mono ${d.change_pct>=0?'positive':'negative'}">${d.change_pct>=0?'+':''}${num(d.change_pct)}%</td><td>${spark(d.spark,d.change_pct>=0)}</td><td>${pill(d.regime,d.regime==='UPTREND'?'green':d.regime==='DOWNTREND'?'red':'gray')}</td><td class="mono">${num(d.relative_volume)}x</td><td><div class="score-cell"><span>${d.setup_score}</span><div class="score-track"><span style="width:${d.setup_score}%"></span></div></div></td><td>${pill(d.rule_pass?'RULE MATCH':'WATCH',d.rule_pass?'violet':'gray')}</td></tr>`).join('');}
function renderTerminal(){const a=state.analysis,r=a.last,d=a.dataset,estimate=researchEstimate(),plan=planFromAnalysis();const matches=state.rows.filter(x=>x.rule_pass).length;const modeButtons=['Swing','Intraday','Delivery'].map(m=>`<button data-mode="${m}" class="${state.mode===m?'selected':''}">${m}</button>`).join('');const confidence=estimate?.current_probability;$('#content').innerHTML=
 heading('Research terminal','Discover the setup. Test the edge. Know the risk.',`<button class="button subtle" data-page="data">\u2191 Import history</button><button class="button primary" data-page="lab">\u2727 Open AI lab</button>`)+
 demoBanner(d.synthetic)+`<div class="stats">${stat('DATASETS IN VIEW',state.rows.length,`${state.mode} \u00b7 ${strategySpec().timeframe} history`)}${stat('LATEST RULE MATCHES',matches,'Rule matches are not trade recommendations')}${stat('PAPER CAPITAL',money(state.boot.account.settings.capital),'0.5% planned risk limit \u00b7 no leverage')}${stat('EXECUTION STATUS','Research only','Live orders disabled by design','purple-text')}</div>
 <div class="toolbar"><div class="segmented">${modeButtons}</div><select class="select-inline" id="terminal-strategy" aria-label="Strategy">${options(state.boot.strategies.filter(s=>s.mode===state.mode),state.strategy)}</select><span class="small muted right">${pill('NOT LIVE','amber')}</span><input id="symbol-search" class="search" placeholder="Search research universe..." aria-label="Search symbols"></div>
 <div class="two-column"><section class="panel"><div class="panel-head"><div class="chart-title"><span class="ticker-square">${h(d.symbol.replace('SIM-','').slice(0,2))}</span><div><h2 class="chart-symbol">${h(d.symbol)}</h2><small>${h(d.source)} \u00b7 ${h(d.timeframe)} candles</small></div></div>${pill(d.synthetic?'SYNTHETIC':'HISTORICAL',d.synthetic?'amber':'gray')}</div><div class="chart-price-row"><div class="row-flex"><div class="chart-price mono">${money(r.c,2)}</div><span class="small ${state.rows.find(x=>x.id===state.dataset)?.change_pct>=0?'positive':'negative'}">${num(state.rows.find(x=>x.id===state.dataset)?.change_pct)}% last bar</span></div><div class="zoom-buttons">${[60,120,180].map(z=>`<button data-zoom="${z}" class="${z===state.zoom?'selected':''}">${z} bars</button>`).join('')}</div></div><div class="chart-legend"><span><b class="legend-ema20"></b>EMA 20</span><span><b class="legend-ema50"></b>EMA 50</span><span>Volume below</span></div><div class="price-chart" id="price-chart"></div><div class="chart-bottom"><span>Last completed bar: ${h(day(r.t))} ${h(r.t.slice(11,16))} IST</span><span>OHLCV \u00b7 local history</span></div><div class="chart-context"><div><small>RSI (14)</small><strong>${num(r.rsi,1)}</strong></div><div><small>ATR (14)</small><strong>${money(r.atr,2)}</strong></div><div><small>PRIOR 20-BAR LOW</small><strong>${money(r.support,2)}</strong></div><div><small>PRIOR 20-BAR HIGH</small><strong>${money(r.resistance,2)}</strong></div><div><small>RELATIVE VOLUME</small><strong>${num(r.rv,2)}x</strong></div><div><small>${state.mode==='Intraday'?'SESSION VWAP':'EMA 50'}</small><strong>${money(state.mode==='Intraday'?r.vwap:r.ema50,2)}</strong></div></div></section>
 <section class="panel"><div class="panel-head"><h3>Setup intelligence</h3>${pill(a.rule_pass?'RULE MATCH':'WATCH',a.rule_pass?'violet':'gray')}</div><div class="panel-body"><div class="small muted">${confidence==null?'Rule checklist score':'Estimated target-hit probability'}</div><div class="confidence-line"><span class="confidence-number">${confidence==null?a.setup_score:num(confidence*100,1)}</span><span class="confidence-unit">${confidence==null?'/ 100':'%'}</span></div><div class="meter"><span style="width:${confidence==null?a.setup_score:confidence*100}%"></span></div><p class="definition">${confidence==null?'A transparent setup checklist, not a win probability. Run the AI lab to estimate a defined trade outcome.':`From ${h(estimate.selected_model||'research')}. Historical and conditional; not the probability of net profit. ${d.synthetic?'Synthetic evidence only.':''}`}</p>${estimate?`<div class="tag-row">${pill((estimate.evidence_status||'UNVERIFIED').replaceAll('_',' '),'amber')}</div>`:''}<ul class="evidence-list">${a.checks.map(x=>`<li>${passIcon(x.pass)}${h(x.name)}</li>`).join('')}</ul><button class="button primary full" data-action="run-selected">Compare AI models <span>\u2197</span></button><div class="divider"></div><div class="signal-header"><h3>Reference plan</h3><span class="tiny muted">LONG ONLY</span></div><div class="plan-grid"><div><small>LAST-CLOSE REFERENCE</small><b class="mono">${money(plan.entry,2)}</b></div><div><small>ILLUSTRATIVE STOP</small><b class="mono negative">${money(plan.stop,2)}</b></div><div><small>ILLUSTRATIVE 2R TARGET</small><b class="mono positive">${money(plan.target,2)}</b></div><div><small>RISK-CAPPED QUANTITY</small><b class="mono">${plan.q} shares</b></div></div><p class="paper-note">Not an entry instruction. Actual next-open price, spread and gaps are unknown. Planned risk: ${money(plan.risk,2)}, including estimated fees; actual loss can exceed it.</p></div></section></div>
 <section class="panel"><div class="panel-head"><div><h3>Opportunity scanner</h3><small>${h(strategySpec().name)} \u00b7 ranked by rule checklist, not by predicted returns</small></div><span class="tiny muted">${state.rows.length} datasets</span></div><div class="table-wrap"><table id="scanner-table"><thead><tr><th>Symbol / source</th><th>Last close</th><th>Last change</th><th>Price history</th><th>Regime</th><th>Rel. volume</th><th>Checklist</th><th>Rule state</th></tr></thead><tbody>${scannerRows()}</tbody></table></div><div class="table-note">Relative volume is compared with prior 20 bars for daily data and the same time slot in prior sessions for intraday. This table covers local datasets. Use Market Explorer for NSE/BSE search and Daily Trade Desk for watched quote snapshots.</div></section>`;drawPriceChart();}
function drawPriceChart(){const el=$('#price-chart');if(!el||!state.analysis)return;const bars=state.analysis.chart.slice(-state.zoom),W=920,H=365,L=10,R=65,top=20,priceH=240,volumeTop=286,volumeH=43;const low=Math.min(...bars.map(b=>b.l)),high=Math.max(...bars.map(b=>b.h)),pad=(high-low)*.1||1,min=low-pad,max=high+pad;const width=W-L-R,dx=width/bars.length,candle=Math.max(1.2,dx*.58);const y=v=>top+(max-v)/(max-min)*priceH;const x=i=>L+(i+.5)*dx;const maxv=Math.max(...bars.map(b=>b.v),1);let shapes='';for(let k=0;k<6;k++){let val=min+(max-min)*k/5,Y=y(val);shapes+=`<line x1="${L}" y1="${Y}" x2="${W-R}" y2="${Y}" stroke="#29303c" stroke-width=".6"/><text x="${W-R+12}" y="${Y+4}" fill="#7d8aa0" font-size="10" font-family="monospace">${num(val,1)}</text>`;}
 bars.forEach((b,i)=>{const col=b.c>=b.o?'#58cdaa':'#dd7d8b',xx=x(i);shapes+=`<line x1="${xx}" x2="${xx}" y1="${y(b.h)}" y2="${y(b.l)}" stroke="${col}" stroke-width="1"/><rect x="${xx-candle/2}" y="${Math.min(y(b.o),y(b.c))}" width="${candle}" height="${Math.max(1,Math.abs(y(b.c)-y(b.o)))}" fill="${col}"/><rect x="${xx-candle/2}" y="${volumeTop+volumeH-b.v/maxv*volumeH}" width="${candle}" height="${b.v/maxv*volumeH}" fill="${col}" opacity=".38"/>`;});
 for(const [key,col] of [['ema20','#e0b475'],['ema50','#a594eb']])shapes+=`<polyline points="${bars.map((b,i)=>x(i)+','+y(b[key])).join(' ')}" fill="none" stroke="${col}" stroke-width="1.4"/>`;
 for(let k=0;k<5;k++){const i=Math.floor((bars.length-1)*k/4),txt=bars[i].t.slice(5,10)+(state.mode==='Intraday'?' '+bars[i].t.slice(11,16):'');shapes+=`<text x="${Math.max(8,Math.min(W-R-50,x(i)-18))}" y="350" fill="#7d8aa0" font-size="10">${h(txt)}</text>`;}
 const last=bars.at(-1);shapes+=`<line x1="${L}" y1="${y(last.c)}" x2="${W-R}" y2="${y(last.c)}" stroke="#7aa998" stroke-dasharray="3,5" opacity=".5"/><line x1="${L}" y1="277" x2="${W-R}" y2="277" stroke="#2b3240"/><text x="${W/2}" y="140" text-anchor="middle" fill="#8991a8" opacity=".08" font-size="43" font-weight="600">${state.analysis.dataset.synthetic?'SYNTHETIC':'HISTORICAL'}</text>`;
 el.innerHTML=`<svg id="candle-svg" viewBox="0 0 ${W} ${H}" aria-label="Historical candlestick chart with EMA overlays and volume">${shapes}<line id="crosshair" y1="12" y2="331" stroke="#9cabc2" stroke-dasharray="3,4" opacity="0"/></svg><div class="chart-tooltip"></div>`;
 const svg=$('svg',el),tip=$('.chart-tooltip',el);svg.addEventListener('mousemove',evt=>{const rect=svg.getBoundingClientRect(),mx=(evt.clientX-rect.left)/rect.width*W,idx=Math.max(0,Math.min(bars.length-1,Math.floor((mx-L)/dx))),b=bars[idx];const line=$('#crosshair');line.setAttribute('x1',x(idx));line.setAttribute('x2',x(idx));line.setAttribute('opacity','.6');tip.textContent=`${b.t.slice(0,16).replace('T',' ')}  O ${num(b.o)}  H ${num(b.h)}  L ${num(b.l)}  C ${num(b.c)}  V ${num(b.v,0)}`;tip.style.display='block';});svg.addEventListener('mouseleave',()=>{tip.style.display='none';$('#crosshair').setAttribute('opacity','0');});}
function renderStrategies(){$('#content').innerHTML=heading('A strategy is a hypothesis.','Five implemented, inspectable rule families. No secret algorithm or promised win rate.',`<button class="button subtle" data-page="lab">Open comparison lab \u2197</button>`,'STRATEGY RESEARCH')+`<div class="banner info"><p><strong>Rules generate setups. ML filters them.</strong> Every algorithm is tested against a constant base-rate forecast and a rules-only trading baseline. A simpler model is allowed to win.</p></div><div class="three-columns">${state.boot.strategies.map((s,i)=>`<section class="panel strategy-card"><div class="panel-body"><div class="strategy-icon"><span>${['\u2197','\u25c7','\u2301','\u25a5','\u224b'][i]}</span>${pill(s.mode,s.mode==='Intraday'?'amber':'violet')}</div><h3>${h(s.name)}</h3><p>${h(s.description)}</p><div class="strategy-meta"><span>${h(s.timeframe)} candles</span><span>${s.horizon}-bar maximum horizon</span></div><button class="button full" data-strategy="${s.id}">Research this strategy \u2192</button></div></section>`).join('')}<section class="panel strategy-card"><div class="panel-body"><div class="strategy-icon">\u2727 ${pill('MODEL COMPARISON','gray')}</div><h3>Calibrated ML filters</h3><p>Logistic regression, Extra Trees, histogram gradient boosting and a calibrated-member soft vote. Separate calibration, model selection, final testing and optional walk-forward checks.</p><div class="strategy-meta"><span>Champion selected on Brier score</span></div><button class="button full subtle" data-page="lab">Open AI lab \u2192</button></div></section></div>`;}
function renderLab(){const spec=strategySpec(),datasets=compatible();if(!datasets.some(d=>d.id===state.dataset))state.dataset=datasets[0]?.id;$('#content').innerHTML=heading('AI strategy lab','Test the rule. Compare the models. Inspect the untouched period.',`<button class="button subtle" data-page="strategies">\u2190 Strategy library</button>`,'CALIBRATED, CHRONOLOGICAL RESEARCH')+
 `<section class="panel"><div class="panel-head"><h3>Experiment configuration</h3>${pill('LONG-ONLY CASH EQUITIES','gray')}</div><div class="panel-body"><form id="study-form"><div class="form-grid"><div class="field"><label for="lab-strategy">Strategy family</label><select id="lab-strategy">${options(state.boot.strategies,state.strategy)}</select></div><div class="field"><label for="lab-dataset">Dataset</label><select id="lab-dataset">${datasetOptions()}</select></div><div class="field"><label for="threshold">Minimum target-hit estimate</label><input id="threshold" type="number" value="0.60" min="0.50" max="0.95" step="0.01"><small>Fixed before testing; not an accuracy target.</small></div><div class="field"><label for="horizon">Maximum holding horizon (bars)</label><input id="horizon" type="number" value="${spec.horizon}" min="1" max="${spec.timeframe==='15m'?24:40}"></div><div class="field"><label for="costs">Round-trip estimated charges (bps)</label><input id="costs" type="number" value="40" min="0" max="500" step="1"><small>Not a broker-accurate Indian tax calculator.</small></div><div class="field"><label for="slippage">Adverse slippage per side (bps)</label><input id="slippage" type="number" value="5" min="0" max="100" step="1"></div></div><label class="inline-check walkforward-toggle"><input id="study-walkforward" type="checkbox" checked> Also evaluate three expanding-history, disjoint walk-forward test windows</label><div class="form-actions"><button type="submit" class="button primary" ${!datasets.length||state.job?'disabled':''}>\u2727 Run model comparison</button><p>Fixed recipes \u00b7 1.5 ATR stop \u00b7 2R target \u00b7 0.5% risk \u00b7 20% exposure cap</p></div></form></div></section><div id="job-container"></div><div id="research-results">${state.result?renderResults(state.result):empty('Your model has to earn its confidence.','Run an experiment to see selection scores, final-test outcomes, probability reliability, a rules-only benchmark and every simulated trade. Insufficient history produces no estimate.')}</div><div id="experiment-history">${experimentHistory()}</div>`;if(state.job)renderProgress(state.job);}
function experimentHistory(){const rs=state.boot.experiments;return `<section class="panel" style="margin-top:22px"><div class="panel-head"><h3>Experiment registry</h3><span class="tiny muted">Versioned data fingerprint \u00b7 fixed configuration</span></div><div class="table-wrap"><table><thead><tr><th>Dataset / strategy</th><th>Selected model</th><th>Evidence state</th><th>Created</th><th></th></tr></thead><tbody>${rs.length?rs.map(r=>`<tr><td><strong>${h(r.symbol)}</strong><small>${h(r.strategy_name)}${r.synthetic?' \u00b7 SYNTHETIC':''}</small></td><td>${h(r.selected_model||'Insufficient evidence')}</td><td>${pill(r.evidence_status.replaceAll('_',' '),r.evidence_status==='RESEARCH_GATES_PASSED'?'green':'amber')}</td><td>${h(day(r.created))}</td><td><button class="experiment-link" data-experiment="${r.id}">Open report \u2197</button></td></tr>`).join(''):'<tr><td colspan="5" class="table-empty">No completed experiments yet.</td></tr>'}</tbody></table></div></section>`;}
function renderProgress(j){const el=$('#job-container');if(el)el.innerHTML=`<div class="progress-wrap"><div class="row-flex"><h3>${h(j.message||'Preparing experiment')}</h3><span class="mono small">${j.progress||0}%</span></div><div class="meter"><span style="width:${j.progress||0}%"></span></div><p>One local research worker. Historical results are not live trading performance.</p></div>`;}
function lineChart(series,width=900,height=245){let all=series.flatMap(s=>s.points.map(p=>p.y));if(!all.length)return '';let lo=Math.min(...all),hi=Math.max(...all),pad=(hi-lo)*.15||10;lo-=pad;hi+=pad;const L=15,R=80,T=15,B=35,y=v=>T+(hi-v)/(hi-lo)*(height-T-B);let out='';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4,Y=y(v);out+=`<line x1="${L}" x2="${width-R}" y1="${Y}" y2="${Y}" stroke="#2c3444" stroke-width=".7"/><text x="${width-R+10}" y="${Y+4}" fill="#8392aa" font-size="10">${num(v,0)}</text>`;}for(const s of series){const n=s.points.length;if(n<2)continue;out+=`<polyline fill="none" stroke="${s.color}" stroke-width="2" points="${s.points.map((p,i)=>`${L+i/(n-1)*(width-L-R)},${y(p.y)}`).join(' ')}"/>`;}const longest=series.reduce((a,b)=>a.points.length>b.points.length?a:b);for(let i=0;i<4;i++){const k=Math.floor((longest.points.length-1)*i/3);out+=`<text x="${L+i/3*(width-L-R-60)}" y="${height-9}" fill="#8392aa" font-size="10">${h(String(longest.points[k]?.x||'').slice(0,10))}</text>`;}return `<svg viewBox="0 0 ${width} ${height}" aria-label="Historical simulated equity comparison">${out}</svg>`;}
function renderResults(r){const m=r.ml_test,b=r.rules_test;const valid=r.current_probability!=null;const modelRows=r.leaderboard.map(x=>`<tr><td><strong>${h(x.model)}</strong>${x.selected?' '+pill('SELECTED','violet'):''}</td><td class="mono">${num(x.selection_brier,4)}</td><td class="mono">${num(x.selection_log_loss,4)}</td><td>${x.selection_events}</td></tr>`).join('');const impmax=Math.max(...r.importance.map(x=>Math.max(0,x.selection_brier_increase)),.00001);return `<div class="result-summary" style="margin-top:24px"><div class="row-flex"><div><h2>${h(r.symbol)} <span class="muted">/</span> ${h(r.strategy_name)}</h2><p class="small muted" style="margin:5px 0 0">${h(r.selected_model||'No model estimate available')} \u00b7 ${r.synthetic?'Synthetic history':'Imported historical data'}</p></div><a class="button subtle small" href="/api/experiments/${r.id}/download" download>\u2193 Export evidence JSON</a></div></div>${r.synthetic?demoBanner(true):''}
 <div class="stats">${stat('ML-FILTERED NET OUTCOME',money(m.net_pnl,2),`${m.n} simulated, non-overlapping trades`,m.net_pnl>=0?'positive':'negative')}${stat('RULES-ONLY NET OUTCOME',money(b.net_pnl,2),`${b.n} trades \u00b7 same final test window`,b.net_pnl>=0?'positive':'negative')}${stat('ML BAR-CLOSE DRAWDOWN',num(m.bar_close_drawdown_pct??0)+'%','Not a tick-level or worst-case loss cap')}${stat('CURRENT TARGET-HIT ESTIMATE',valid?pct(r.current_probability):'Unavailable',valid?'Conditional outcome \u00b7 not net-profit odds':'Not enough independent evidence','purple-text')}</div>
 <div class="banner info"><p><strong>${h(r.evidence_status.replaceAll('_',' '))}.</strong> ${h(r.target_definition)}</p></div><section class="panel"><div class="panel-head"><h3>Chronological evaluation</h3><span class="tiny muted">No random train/test shuffle</span></div><div class="panel-body"><div class="timeline">${r.splits.map(s=>`<div><b>${h(s.name)}</b>${s.events} events<small>${day(s.from)} to ${day(s.to)}</small></div>`).join('')}</div><div class="tiny muted">${r.purged_boundary_events} labels crossing stage boundaries were purged. Calibration, selection and reliability evaluation use non-overlapping events. Training labels may overlap.</div></div></section>
 <div class="equal-columns" style="margin-top:18px"><section class="panel"><div class="panel-head"><h3>Model selection leaderboard</h3><span class="tiny muted">Lower Brier is better</span></div><div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Selection Brier</th><th>Log loss</th><th>Events</th></tr></thead><tbody>${modelRows||'<tr><td colspan="4" class="table-empty">Insufficient samples for independent model comparison.</td></tr>'}</tbody></table></div><div class="table-note">Selection uses probability quality, not final-test profitability. No universal winner is assumed.</div></section><section class="panel"><div class="panel-head"><h3>Evidence gates</h3>${pill(r.evidence_status==='RESEARCH_GATES_PASSED'?'RESEARCH ONLY':'NOT VALIDATED','amber')}</div><div class="panel-body"><ul class="evidence-list">${(r.gates||[]).map(g=>`<li>${passIcon(g.pass)}${h(g.name)}</li>`).join('')||'<li>More data is required before evaluating evidence gates.</li>'}</ul><div class="info-row"><span>Final-test Brier</span><strong class="mono">${num(r.test_brier,4)}</strong></div><div class="info-row"><span>Constant-prior test Brier</span><strong class="mono">${num(r.test_baseline_brier,4)}</strong></div><div class="info-row"><span>Same-exposure buy/hold net</span><strong class="mono">${money(r.buy_hold.net_pnl,2)}</strong></div></div></section></div>
 <section class="panel"><div class="panel-head"><div><h3>Final-test equity</h3><small>Hypothetical bar-close liquidation equity after estimated costs</small></div><div class="tag-row">${pill('ML FILTER','violet')}${pill('RULES ONLY','green')}</div></div><div class="result-chart">${lineChart([{color:'#ac97f5',points:m.curve.map(x=>({x:x.t,y:x.equity}))},{color:'#53c8a5',points:b.curve.map(x=>({x:x.t,y:x.equity}))}])}</div></section>
 <div class="equal-columns" style="margin-top:18px"><section class="panel"><div class="panel-head"><h3>Probability reliability</h3><span class="tiny muted">Final-test cohorts</span></div><div class="table-wrap"><table><thead><tr><th>Bucket</th><th>Predicted</th><th>Observed</th><th>95% interval / n</th></tr></thead><tbody>${r.calibration.length?r.calibration.map(c=>`<tr><td>${pct(c.from,0)}\u2013${pct(c.to,0)}</td><td>${pct(c.predicted)}</td><td>${pct(c.observed)}</td><td class="calibration-cell">${pct(c.observed_wilson_95[0])}\u2013${pct(c.observed_wilson_95[1])}<small>${c.n} events${c.n<30?' \u00b7 thin cohort':''}</small></td></tr>`).join(''):'<tr><td colspan="4" class="table-empty">No calibrated estimate available.</td></tr>'}</tbody></table></div><div class="table-note">Intervals describe observed cohort hit rates under a binomial approximation. They are not an individual trade guarantee and may understate dependence.</div></section><section class="panel"><div class="panel-head"><h3>Model sensitivity</h3><span class="tiny muted">Selection-set permutation</span></div><div class="panel-body">${r.importance.length?r.importance.slice(0,7).map(x=>`<div class="importance-row"><span>${h(x.feature)}</span><div class="bar" style="width:${Math.max(0,x.selection_brier_increase)/impmax*90}px"></div><b class="mono">${num(x.selection_brier_increase,4)}</b></div>`).join(''):'<p class="small muted">No feature sensitivity is attributed to a constant baseline or an untrained model.</p>'}<p class="tiny muted" style="margin-top:15px">Descriptive sensitivity, not a causal explanation or SHAP attribution.</p></div></section></div>
 <section class="panel"><div class="panel-head"><h3>Simulated ML-filtered trades</h3><span class="tiny muted">First 80 shown; full results in export</span></div><div class="table-wrap"><table><thead><tr><th>Signal</th><th>Entry</th><th>Exit</th><th>Qty</th><th>Target-hit estimate</th><th>Outcome</th><th>Net P&amp;L</th></tr></thead><tbody>${m.trades.length?m.trades.slice(0,80).map(t=>`<tr><td>${h(t.signal_time.slice(0,16).replace('T',' '))}</td><td class="mono">${money(t.entry,2)}</td><td class="mono">${money(t.exit,2)}</td><td>${t.quantity}</td><td>${pct(t.probability)}</td><td>${pill(t.reason,t.label?'green':'gray')}</td><td class="mono ${t.net_pnl>=0?'positive':'negative'}">${money(t.net_pnl,2)}</td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">No trades cleared the configured probability and position-size filters. That is a valid result.</td></tr>'}</tbody></table></div></section>
 ${walkforwardView(r)}<div class="warning-list">${r.warnings.map(w=>`<p>\u2022 ${h(w)}</p>`).join('')}</div><div class="tiny muted">Data fingerprint: <span class="mono">${h(r.data_sha256.slice(0,24))}...</span> \u00b7 ${h(r.engine_version)} \u00b7 Record ${h(r.id)}</div>`;}
async function startStudy(config){if(state.job)return;const res=await api('/studies',{dataset_id:state.dataset,strategy:state.strategy,config,walkforward:$('#study-walkforward')?.checked??false});if(res.cached){await openExperiment(res.result_id);toast('Loaded the identical cached experiment; no fresh test evidence was created.');return;}state.job={id:res.job_id,progress:0,message:'Preparing experiment'};if(state.page!=='lab')await navigate('lab');renderProgress(state.job);pollStudy();}
async function pollStudy(){if(!state.job)return;try{const j=await api('/jobs/'+state.job.id);state.job=j;if(j.status==='complete'){state.job=null;await openExperiment(j.result_id);toast('Research report saved. Review failures as carefully as passing gates.');return;}if(j.status==='failed'){state.job=null;throw Error(j.error||'Experiment failed');}renderProgress(j);setTimeout(pollStudy,700);}catch(err){state.job=null;toast(err.message,true);if(state.page==='lab')renderLab();}}
async function openExperiment(id){state.result=await api('/experiments/'+id);state.strategy=state.result.strategy;state.dataset=state.result.dataset_id;state.mode=strategySpec().mode;state.boot.experiments=await api('/experiments');if(state.page!=='lab')await navigate('lab');else renderLab();}
function renderPaper(){const a=state.boot.account,s=a.settings,d=state.boot.datasets.find(x=>x.id===state.dataset)||state.boot.datasets[0];const p=state.analysis&&state.analysis.dataset.id===d?.id?planFromAnalysis():null;$('#content').innerHTML=heading('Paper portfolio','Practice the workflow without sending a real broker order.',`<button class="button subtle" data-page="risk">View risk & audit \u2197</button>`,'MANUAL SIMULATION JOURNAL')+`<div class="banner"><p><strong>Manual fills only.</strong> Stops and targets are journal fields, not automatic orders. Open-position equity is valued at entry cost, not at live market prices. Synthetic and imported-data positions stay visibly labelled.</p></div><div class="stats">${stat('AVAILABLE VIRTUAL CASH',money(a.cash,2),'Initial paper allocation: '+money(s.capital))}${stat('REALIZED NET P&L',money(a.realized_pnl,2),'Includes the journal\'s estimated fees',a.realized_pnl>=0?'positive':'negative')}${stat('PLANNED OPEN RISK',money(a.open_planned_risk,2),'Combined limit: '+money(s.capital*s.total_risk_pct/100))}${stat('OPEN POSITIONS',a.open_positions.length,`${s.max_positions} maximum \u00b7 no leverage`)}</div><div class="two-column"><section class="panel"><div class="panel-head"><h3>Record a paper entry</h3>${pill('MANUAL LONG','violet')}</div><div class="panel-body"><form id="paper-form"><div class="form-grid"><div class="field full"><label for="paper-dataset">Dataset / instrument</label><select id="paper-dataset">${state.boot.datasets.map(x=>`<option value="${x.id}" ${x.id===d?.id?'selected':''}>${h(x.symbol)} \u00b7 ${x.timeframe}${x.synthetic?' \u00b7 SYNTHETIC':''}</option>`).join('')}</select></div><div class="field"><label for="paper-entry">Manual fill price</label><input type="number" id="paper-entry" min="0.01" step="0.01" value="${num(p?.entry||d?.close||100).replaceAll(',','')}"></div><div class="field"><label for="paper-stop">Planned stop</label><input type="number" id="paper-stop" min="0.01" step="0.01" value="${num(p?.stop||(d?.close||100)*.97).replaceAll(',','')}"></div><div class="field"><label for="paper-target">Planned target</label><input type="number" id="paper-target" min="0.01" step="0.01" value="${num(p?.target||(d?.close||100)*1.06).replaceAll(',','')}"></div><div class="field"><label for="paper-qty">Shares</label><input type="number" id="paper-qty" min="1" step="1" value="${Math.max(1,p?.q||1)}"></div></div><label class="check-label"><input type="checkbox" id="paper-ack" required><span>I am entering a manual simulated fill. This does not buy shares or place a stop order.</span></label><div class="form-actions"><button class="button primary" type="submit">Record paper entry</button><p>Risk and cash limits are checked on the server.</p></div></form></div></section><section class="panel"><div class="panel-head"><h3>Account guardrails</h3>${pill(s.kill_switch?'ENTRIES BLOCKED':'ACTIVE',s.kill_switch?'red':'green')}</div><div class="panel-body">${[['Risk per trade',`${s.risk_pct}% / ${money(s.capital*s.risk_pct/100)}`],['Maximum position',`${s.exposure_pct}% of capital`],['Total planned open risk',`${s.total_risk_pct}%`],['Daily realized-loss stop',`${s.daily_loss_pct}%`],['Cumulative loss review','5%'],['Simultaneous positions',s.max_positions],['Estimated round-trip fees',`${s.cost_bps} bps`],['Broker execution','NOT IMPLEMENTED']].map(([k,v])=>`<div class="info-row"><span>${h(k)}</span><strong>${h(v)}</strong></div>`).join('')}<div class="divider"></div><p class="note-block">These limits constrain the simulated journal. Real stop fills, gaps, slippage and platform failures can produce larger losses.</p></div></section></div><section class="panel"><div class="panel-head"><h3>Open paper positions</h3><span class="tiny muted">Close manually using an observed or simulated price</span></div><div class="table-wrap"><table><thead><tr><th>Instrument</th><th>Qty</th><th>Entry</th><th>Stop / target</th><th>Entry fees</th><th></th></tr></thead><tbody>${a.open_positions.length?a.open_positions.map(x=>`<tr><td><strong>${h(x.symbol)}</strong><small>${x.synthetic?'SYNTHETIC':'IMPORTED DATA'} \u00b7 manual fill</small></td><td>${x.quantity}</td><td>${money(x.entry,2)}</td><td>${money(x.stop,2)} / ${money(x.target,2)}</td><td>${money(x.entry_fee,2)}</td><td><button class="button small" data-close-position="${x.id}">Close manually</button></td></tr>`).join(''):'<tr><td colspan="6" class="table-empty">No open paper positions.</td></tr>'}</tbody></table></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>Closed paper trades</h3></div><div class="table-wrap"><table><thead><tr><th>Instrument</th><th>Qty</th><th>Entry</th><th>Exit</th><th>Net P&L</th><th>Closed</th></tr></thead><tbody>${a.closed_positions.length?a.closed_positions.map(x=>`<tr><td>${h(x.symbol)}<small>${x.synthetic?'SYNTHETIC':'IMPORTED DATA'}</small></td><td>${x.quantity}</td><td>${money(x.entry,2)}</td><td>${money(x.exit,2)}</td><td class="${x.pnl>=0?'positive':'negative'}">${money(x.pnl,2)}</td><td>${day(x.closed)}</td></tr>`).join(''):'<tr><td colspan="6" class="table-empty">Your manually closed trades will appear here.</td></tr>'}</tbody></table></div></section>`;}
function renderData(){$('#content').innerHTML=heading('Your data. Your evidence.','Start offline. Import real history when you are ready. Never mix demo prices with live quotes.','','DATA & CONNECTIONS')+`<div class="three-columns"><section class="panel"><div class="panel-body"><div class="signal-header"><h3>Offline demo</h3>${pill('INCLUDED','green')}</div><p class="note-block">Six fictional daily series and three intraday series. All seeded and reproducible. They test the software, not the market.</p></div></section><section class="panel"><div class="panel-body"><div class="signal-header"><h3>OHLCV CSV</h3>${pill('AVAILABLE','green')}</div><p class="note-block">Import historical daily or 15-minute candles. Strict schema, duplicate, price, timeframe and incomplete-candle checks.</p></div></section><section class="panel"><div class="panel-body"><div class="signal-header"><h3>Upstox history</h3>${pill(state.boot.providers.upstox_configured?'TOKEN PRESENT':'NOT CONFIGURED',state.boot.providers.upstox_configured?'violet':'gray')}</div><p class="note-block">Read-only V3 historical adapter. Token presence does not verify authorization. No live WebSocket or order service.</p></div></section></div><div class="equal-columns"><section class="panel"><div class="panel-head"><h3>Import a CSV dataset</h3>${pill('LOCAL ONLY','violet')}</div><div class="panel-body"><form id="import-form"><div class="form-grid"><div class="field"><label for="import-symbol">Symbol</label><input id="import-symbol" placeholder="RELIANCE" maxlength="24" required></div><div class="field"><label for="import-frame">Bar interval</label><select id="import-frame"><option value="1d">Daily</option><option value="15m">15 minutes</option></select></div><div class="field"><label for="import-source">Source label</label><input id="import-source" placeholder="Broker export" maxlength="120" value="User-provided CSV"></div><div class="field full"><label for="import-file">CSV file (maximum 4 MB / 15,000 rows)</label><input type="file" id="import-file" accept=".csv,text/csv" required></div></div><div class="code" style="margin-top:16px">timestamp,open,high,low,close,volume<br>2026-10-30T09:15:00+05:30,200,204,198,202,150000</div><p class="note-block" style="margin-top:12px">At least 70 completed bars for charts. Consider several years for daily-model research. Timestamps must mark bar opening times. Daily current-date bars are withheld until 16:00 IST. Import only data you are entitled to use.</p><button type="submit" class="button primary">Validate & import history</button></form></div></section><section class="panel"><div class="panel-head"><h3>Read-only broker history</h3>${pill('OPTIONAL','gray')}</div><div class="panel-body"><p class="note-block">Copy <strong>.env.example</strong> to <strong>.env</strong> in the project folder, set your own <strong>UPSTOX_ACCESS_TOKEN</strong>, and restart the service. Credentials remain on your server.</p><form id="upstox-form"><div class="form-grid"><div class="field"><label for="up-symbol">Symbol label</label><input id="up-symbol" placeholder="RELIANCE" required></div><div class="field"><label for="up-frame">Interval</label><select id="up-frame"><option value="1d">Daily</option><option value="15m">15 minutes</option></select></div><div class="field full"><label for="up-key">Exact broker instrument key</label><input id="up-key" placeholder="NSE_EQ|... from the instrument master" required></div><div class="field"><label for="up-start">From date</label><input id="up-start" type="date" value="2020-01-01" required></div><div class="field"><label for="up-end">To date</label><input id="up-end" type="date" value="2026-10-30" required></div></div><div class="form-actions"><button type="submit" class="button subtle">Fetch authorized history</button></div></form><p class="paper-note">Adapter code is included. Connectivity and entitlements require your account and have not been verified here. Requests use only the fixed Upstox historical endpoint.</p></div></section></div><section class="panel"><div class="panel-head"><h3>Dataset registry</h3><span class="tiny muted">Content hashes prevent silent experiment substitution</span></div><div class="table-wrap"><table><thead><tr><th>Instrument</th><th>Source</th><th>Bars</th><th>History</th><th>Fingerprint</th></tr></thead><tbody>${state.boot.datasets.map(d=>`<tr><td><strong>${h(d.symbol)}</strong><small>${d.timeframe}${d.synthetic?' \u00b7 SYNTHETIC':''}</small></td><td>${h(d.source)}</td><td>${num(d.count,0)}</td><td>${day(d.first)} \u2192 ${day(d.last)}</td><td class="mono tiny">${h(d.sha.slice(0,14))}...</td></tr>`).join('')}</tbody></table></div></section>`;}
function renderRisk(audit){const a=state.boot.account,s=a.settings;$('#content').innerHTML=heading('Risk is a separate system.','A model score cannot override account limits or create permission to execute.','','CONTROLS & AUDIT')+`<div class="equal-columns"><section class="panel"><div class="panel-head"><h3>Paper account controls</h3>${pill(s.kill_switch?'PAUSED':'ACTIVE',s.kill_switch?'red':'green')}</div><div class="panel-body"><div class="settings-row"><div><h4>Emergency paper-entry block</h4><p>Stops new journal positions. Manual closes remain available.</p></div><button class="button ${s.kill_switch?'subtle':'danger'}" data-action="toggle-kill">${s.kill_switch?'Resume paper entries':'Block paper entries'}</button></div>${[['Per-trade planned loss','0.5% of current realized equity, including estimated charges'],['Total planned open risk','1% across at most two open positions'],['Maximum per-position allocation','20% of capital; cash-only, no leverage'],['Loss review stops','1% daily realized loss; 5% cumulative realized loss'],['Mutation protection','Local session token, origin/host checks and transactional writes']].map(([k,v])=>`<div class="settings-row"><div><h4>${h(k)}</h4><p>${h(v)}</p></div>${pill('IMPLEMENTED','green')}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h3>Release boundary</h3>${pill('NOT PUBLIC SAAS','amber')}</div><div class="panel-body">${[['Browser interface + Python API','Implemented locally','green'],['Historical CSV + synthetic data','Implemented','green'],['Calibrated ML comparison','Implemented, not profitable by assumption','green'],['Read-only broker snapshots','Adapter implemented; authenticated verification required','amber'],['Real broker orders','Intentionally disabled','gray'],['Multi-user identity / tenancy / billing','Not implemented','gray'],['Independent security / compliance audit','Not completed','amber'],['Windows-specific binary policy','Requires verification on your machine','amber']].map(([k,v,c])=>`<div class="settings-row"><div><h4>${h(k)}</h4><p>${h(v)}</p></div>${pill(c==='green'?'READY FOR LOCAL TEST':'RELEASE GATE',c)}</div>`).join('')}<p class="note-block" style="margin-top:16px">The app intentionally binds to localhost. Read <strong>docs/PRODUCTION_GATES.md</strong> before deploying a customer-facing service. Do not expose this workspace to the public internet.</p></div></section></div><section class="panel"><div class="panel-head"><h3>Local audit trail</h3><span class="tiny muted">Last 100 events \u00b7 append-only through this application, not tamper-proof storage</span></div><div class="table-wrap"><table><thead><tr><th>Time (IST)</th><th>Action</th><th>Details</th></tr></thead><tbody>${audit.map(r=>`<tr><td>${h(r.at.slice(0,19).replace('T',' '))}</td><td>${h(r.action)}</td><td class="audit-detail">${h(r.detail)}</td></tr>`).join('')||'<tr><td colspan="3" class="table-empty">No audit events.</td></tr>'}</tbody></table></div></section>`;}
function renderOptions(){$('#content').innerHTML=heading('Defined-risk options lab','Understand an expiry payoff before considering any options strategy.','','F&O / MATHEMATICAL SCENARIOS')+`<div class="banner"><p><strong>No options trade signals are generated.</strong> This calculator models a same-expiry vertical debit spread held to expiry. No current option chain, lot-size master, broker margin, assignment or physical-settlement model is connected.</p></div><div class="equal-columns"><section class="panel"><div class="panel-head"><h3>Vertical debit-spread scenario</h3>${pill('EDUCATIONAL','amber')}</div><div class="panel-body"><form id="options-form"><div class="form-grid"><div class="field full"><label for="option-kind">Structure</label><select id="option-kind"><option value="bull_call">Bull call debit spread</option><option value="bear_put">Bear put debit spread</option></select></div><div class="field"><label for="option-long">Long strike</label><input id="option-long" type="number" min="1" value="20000" required></div><div class="field"><label for="option-short">Short strike</label><input id="option-short" type="number" min="1" value="20100" required></div><div class="field"><label for="option-debit">Net premium debit per unit</label><input id="option-debit" type="number" min="0.01" step="0.01" value="40" required></div><div class="field"><label for="option-size">Contract lot size (verify with broker)</label><input id="option-size" type="number" min="1" step="1" value="1" required></div><div class="field"><label for="option-lots">Number of lots</label><input id="option-lots" type="number" min="1" step="1" value="1" required></div><div class="field"><label for="option-costs">Estimated total charges (rupees)</label><input id="option-costs" type="number" min="0" step="0.01" value="10" required></div></div><p class="note-block" style="margin-top:14px">Example strikes and lot size are fictional. A lot size of 1 is a mathematical unit, not an Indian exchange contract specification.</p><button class="button primary" type="submit">Calculate expiry payoff</button></form></div></section><section class="panel"><div class="panel-head"><h3>Risk envelope</h3></div><div class="panel-body" id="option-results">${empty('Calculate a scenario','The output will show maximum theoretical loss, maximum theoretical gain, break-even and whether the loss fits your paper risk budget. It will not show invented AI confidence.')}</div></section></div><section class="panel" id="option-chart-panel" hidden><div class="panel-head"><h3>Expiry payoff</h3><span class="tiny muted">Not a forecast of option prices before expiry</span></div><div class="result-chart" id="option-chart"></div></section>`;}
async function refreshBoot(){const b=await api('/bootstrap');state.boot=b;updateChrome();}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-page]');const mode=e.target.closest('[data-mode]');const row=e.target.closest('[data-symbol]');const strategy=e.target.closest('[data-strategy]');const zoom=e.target.closest('[data-zoom]');const exp=e.target.closest('[data-experiment]');const close=e.target.closest('[data-close-position]');const action=e.target.closest('[data-action]');try{if(nav){await navigate(nav.dataset.page);return;}if(mode){setDefaultsForMode(mode.dataset.mode);await navigate('terminal');return;}if(row){state.dataset=row.dataset.symbol;state.analysis=await api('/analysis/'+state.dataset+'?strategy='+state.strategy);renderTerminal();return;}if(strategy){state.strategy=strategy.dataset.strategy;state.mode=strategySpec().mode;state.result=null;await navigate('lab');return;}if(zoom){state.zoom=Number(zoom.dataset.zoom);renderTerminal();return;}if(exp){await openExperiment(exp.dataset.experiment);return;}if(close){const val=prompt('Enter the manual simulated exit fill price. No broker order will be placed.');if(val===null)return;await api('/paper/'+close.dataset.closePosition+'/close',{price:Number(val)});await navigate('paper');toast('Paper position closed and recorded.');return;}if(e.target.closest('#kill-top')||action?.dataset.action==='toggle-kill'){const enabled=!state.boot.account.settings.kill_switch;await api('/kill-switch',{enabled});state.boot.account=await api('/account');updateChrome();if(state.page==='risk')renderRisk(await api('/audit'));if(state.page==='paper')renderPaper();toast(enabled?'New paper entries are blocked. Manual closes still work.':'Paper entries resumed.');return;}if(action?.dataset.action==='run-selected'){await navigate('lab');return;}}catch(err){toast(err.message,true);}});
document.addEventListener('change',async e=>{try{if(e.target.id==='terminal-strategy'){state.strategy=e.target.value;state.result=null;await navigate('terminal');}if(e.target.id==='lab-strategy'){state.strategy=e.target.value;state.mode=strategySpec().mode;state.result=null;renderLab();}if(e.target.id==='lab-dataset'){state.dataset=e.target.value;state.result=null;renderLab();}if(e.target.id==='paper-dataset'){const d=state.boot.datasets.find(d=>d.id===e.target.value);$('#paper-entry').value=d.close.toFixed(2);$('#paper-stop').value=(d.close*.97).toFixed(2);$('#paper-target').value=(d.close*1.06).toFixed(2);$('#paper-qty').value=1;}if(e.target.id==='option-kind'){const bear=e.target.value==='bear_put';$('#option-long').value=bear?20100:20000;$('#option-short').value=bear?20000:20100;}}catch(err){toast(err.message,true);}});
document.addEventListener('input',e=>{if(e.target.id==='symbol-search'){const q=e.target.value.trim().toUpperCase();for(const tr of $$('#scanner-table tbody tr'))tr.hidden=!tr.textContent.toUpperCase().includes(q);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=$('button[type="submit"]',form);if(button)button.disabled=true;try{if(form.id==='study-form'){state.dataset=$('#lab-dataset').value;await startStudy({horizon:Number($('#horizon').value),threshold:Number($('#threshold').value),roundtrip_cost_bps:Number($('#costs').value),slippage_bps:Number($('#slippage').value)});}else if(form.id==='import-form'){const file=$('#import-file').files[0];if(!file)throw Error('Select a CSV file.');if(file.size>4000000)throw Error('CSV limit is 4 MB.');const timeframe=$('#import-frame').value;const r=await api('/import/csv',{symbol:$('#import-symbol').value,timeframe,source:$('#import-source').value,csv_text:await file.text()});await refreshBoot();setDefaultsForMode(timeframe==='15m'?'Intraday':'Swing');state.dataset=r.id;await navigate('terminal');toast(`Imported ${r.bars} completed bars. Review data provenance before research.`);}else if(form.id==='upstox-form'){const timeframe=$('#up-frame').value;const r=await api('/import/upstox',{symbol:$('#up-symbol').value,timeframe,instrument_key:$('#up-key').value,start:$('#up-start').value,end:$('#up-end').value});await refreshBoot();setDefaultsForMode(timeframe==='15m'?'Intraday':'Swing');state.dataset=r.id;await navigate('terminal');toast(`Retrieved ${r.bars} historical bars. This is not a live feed.`);}else if(form.id==='paper-form'){await api('/paper/open',{request_id:requestKey(),dataset_id:$('#paper-dataset').value,quantity:Number($('#paper-qty').value),entry:Number($('#paper-entry').value),stop:Number($('#paper-stop').value),target:Number($('#paper-target').value),acknowledged_manual:$('#paper-ack').checked});await navigate('paper');toast('Manual paper entry saved. No broker order was placed.');}else if(form.id==='options-form'){const r=await api('/options/payoff',{kind:$('#option-kind').value,long_strike:Number($('#option-long').value),short_strike:Number($('#option-short').value),net_debit:Number($('#option-debit').value),lot_size:Number($('#option-size').value),lots:Number($('#option-lots').value),charges:Number($('#option-costs').value)});$('#option-results').innerHTML=`<div class="options-summary">${stat('MAXIMUM THEORETICAL LOSS',money(r.max_loss,2),'At expiry, including supplied charges','negative')}${stat('MAXIMUM THEORETICAL GAIN',money(r.max_gain,2),'At expiry, including supplied charges','positive')}</div><div class="info-row"><span>Break-even underlying price</span><strong>${r.break_even==null?'No profitable region':money(r.break_even,2)}</strong></div><div class="info-row"><span>Paper per-trade risk budget</span><strong>${money(r.risk_budget,2)}</strong></div><div class="banner slim"><p><strong>${r.fits_budget?'FITS THEORETICAL PAPER BUDGET':'EXCEEDS PAPER RISK BUDGET'}.</strong> This is not permission to trade. Execution, assignment, settlement and early-close risks are not modeled.</p></div>`;$('#option-chart-panel').hidden=false;$('#option-chart').innerHTML=lineChart([{color:'#a797ed',points:r.payoff.map(p=>({x:num(p.underlying,0),y:p.pnl}))}]);}}catch(err){toast(err.message,true);}finally{if(button&&button.isConnected)button.disabled=false;}});
async function init(){try{state.boot=await api('/bootstrap');state.dataset=state.boot.datasets.find(d=>d.timeframe==='1d')?.id;const page=location.hash.slice(1)||'recommendations';await navigate(page);}catch(err){$('#content').innerHTML=empty('Could not connect to the local service',err.message);}}
init();
